467c4a92d27018b5.text:
The tests most likely to fail are at the edges: the MIN in Treatments protects the list as a whole but not each band, and dt = 0.25 equals the minimum treatment time at the low end of its range. I have put those first among the extreme tests, and kept two behaviour tests and a knockout to show which structure carries the fit.

[
 {
  "name": "No capacity: the list grows by exactly the referrals",
  "check": "grows_by_referrals",
  "settings": {
   "capacity_0": 0
  },
  "why": "With nothing treated, every referral must stay on the list, so any gap means patients are created or lost."
 },
 {
  "name": "No referrals: the list empties without going negative",
  "check": "empties",
  "settings": {
   "referrals_0": 0
  },
  "why": "Treatments are limited by Waiting_list / Minimum_treatment_time, so the list should drain smoothly towards zero."
 },
 {
  "name": "Capacity at the top of its plausible range",
  "check": "never_negative",
  "settings": {
   "capacity_0": 5000
  },
  "why": "A capacity case is exactly what the model will be used for, so the high end of the range must behave."
 },
 {
  "name": "Ten times the capacity",
  "check": "never_negative",
  "settings": {
   "capacity_0": 39500
  },
  "why": "Far beyond the range, the MIN in Treatments must stop the outflow taking more patients than there are."
 },
 {
  "name": "Urgent cases at top priority with ten times the capacity",
  "check": "never_negative",
  "settings": {
   "priority": 3.0,
   "capacity_0": 39500
  },
  "why": "The MIN protects the list as a whole, not each band; a high Priority can ask the first band for more than it holds."
 },
 {
  "name": "Shortest treatment time with ten times the capacity",
  "check": "never_negative",
  "settings": {
   "minimum_treatment_time": 0.25,
   "capacity_0": 39500
  },
  "why": "At its low end the minimum treatment time equals dt = 0.25, so one Euler step can remove the whole list and the ageing flows then overdraw it."
 },
 {
  "name": "Patients are conserved in the base run",
  "check": "conserved",
  "settings": {},
  "why": "The ageing flows must cancel between bands and every stock must equal its flows added up."
 },
 {
  "name": "Halving dt with three times the capacity",
  "check": "dt_stable",
  "settings": {
   "capacity_0": 11850
  },
  "why": "When the list drains fast the shortest time constant is the 0.5-month minimum treatment time, which a 0.25-month step only just resolves."
 },
 {
  "name": "History within 10% in every month",
  "check": "history_10pct",
  "settings": {},
  "why": "A behaviour test against the reference mode, which a capacity argument relies on."
 },
 {
  "name": "Knock out the list limit on treatments",
  "check": "knockout",
  "equation": {
   "name": "Treatments",
   "eq": "Capacity"
  },
  "expect_change": "none",
  "settings": {},
  "why": "If capacity binds throughout the history, the limit should be dormant there; a large change would mean the limit is shaping the fit."
 },
 {
  "name": "An empty list at the start, with no referrals",
  "check": "empties",
  "settings": {
   "Waiting_0_to_3": 0,
   "Waiting_3_to_6": 0,
   "Waiting_6_to_12": 0,
   "Waiting_12_plus": 0
  },
  "why": "Weighted list is guarded by Smallest_list, so the shares should not divide zero by zero."
 },
 {
  "name": "Boundary: referrals that respond to the wait",
  "check": "person",
  "settings": {},
  "why": "Referrals are exogenous here; the modeller should add a response to the expected wait, with a GP lead, and see whether the case for capacity still holds."
 }
]

